package com.franco.desco.adapter.in.web.crates;import com.franco.desco.application.crates.*;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.crates.CrateModels;import org.springframework.stereotype.Component;
@Component public class CrateWebMapper{public CrateCommands.ListCrates list(int p,int t,Long op){return new CrateCommands.ListCrates(new PageRequest<>(p,t,new CrateCommands.Filter(op),null,null));}public CrateResponses.Summary response(CrateModels.Summary x){return new CrateResponses.Summary(x.operativoVentaId(),x.codigo(),x.estadoProceso(),x.cantidadJabasRecibidas(),x.jabasAsignadas(),x.jabasDevueltasLlenas(),x.jabasDevueltasVacias(),x.jabasDevueltas(),x.jabasDisponibles(),x.jabasPendientes());}public CrateResponses.Balance response(CrateModels.Balance x){return new CrateResponses.Balance(x.operativoVentaId(),x.operativoSocioId(),x.recibidas(),x.asignadas(),x.devueltas(),x.pendientes(),x.disponibles());}public CrateResponses.History response(CrateModels.History x){return new CrateResponses.History(x.jabaMovimientoId(),x.operativoVentaId(),x.operativoSocioId(),x.jabaAsignacionId(),x.jabaDevolucionId(),x.tipoMovimiento(),x.cantidad(),x.fechaHora(),x.motivo(),x.referencia(),x.estado(),x.usuario());}}
